uniform float speed : 0.0 .. 5.0 = 1.0;
uniform float density : 0.0 .. 1.0 = 0.35;
uniform float sparkle : 0.0 .. 5.0 = 2.0;
uniform vec3 tint : color = 0.7, 0.8, 1.0;
uniform bool color = false;

state fixed ph;
state fixed spd;
state fixed den;
state fixed sat;
state fixed one;

void update() {
  ph = fract(ph + fixed(dt * speed));
  spd = fixed(sparkle);
  den = fixed(density);
  sat = fixed(color ? 0.6 : 0.0);
  one = fixed(1.0);
}

vec3 shade(Led led) {
  fixed p = fixed(led.pos.y) * fixed(7.0) + fixed(led.idx) * fixed(0.61803);
  fixed h = hash(float(fract(p)));
  fixed lit = step(fixed(1.0) - den, h);
  fixed tw = fixed(0.5) + fixed(0.5) * sin(fract(p + ph * (fixed(0.5) + h * spd)) * one);
  fixed b = lit * tw * tw;
  fixed hue = fract(h + fract(p * fixed(0.5)) + ph);
  return hsv2rgb(hue, sat, b);
}

